begin;
with j as (select * from jsonb_to_recordset($law7d0031$[{"code_id":"BK_RF","article_number":"58","version_date":"1998-07-31","article_text":"(Наименование в редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 02.08.2019 № 307-ФЗ)\n\n1. Законом субъекта Российской Федерации (за исключением закона субъекта Российской Федерации о бюджете субъекта Российской Федерации или иного закона субъекта Российской Федерации на ограниченный срок действия)  могут быть установлены: (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nединые для всех городских поселений субъекта Российской Федерации нормативы отчислений в бюджеты городских поселений от отдельных федеральных и (или)  региональных налогов и сборов,  налогов,  предусмотренных специальными налоговыми режимами,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством о налогах и сборах в бюджет субъекта Российской Федерации; (В редакции Федерального закона от 29.11.2014 № 383-ФЗ)\n\nединые для всех сельских поселений субъекта Российской Федерации нормативы отчислений в бюджеты сельских поселений от отдельных федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  и (или)  региональных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством Российской Федерации о налогах и сборах в бюджет субъекта Российской Федерации; (Дополнение абзацем - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\nединые для всех муниципальных районов субъекта Российской Федерации нормативы отчислений в бюджеты муниципальных районов от отдельных федеральных и (или)  региональных налогов и сборов,  налогов,  предусмотренных специальными налоговыми режимами,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством о налогах и сборах в бюджет субъекта Российской Федерации; (В редакции Федерального закона от 29.11.2010 № 313-ФЗ)\n\nединые для всех муниципальных округов субъекта Российской Федерации нормативы отчислений в бюджеты муниципальных округов от отдельных федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  и (или)  региональных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством Российской Федерации о налогах и сборах в бюджет субъекта Российской Федерации; (Дополнение абзацем - Федеральный закон от 01.10.2020 № 311-ФЗ)\n\nединые для всех городских округов субъекта Российской Федерации нормативы отчислений в бюджеты городских округов от отдельных федеральных и (или)  региональных налогов и сборов,  налогов,  предусмотренных специальными налоговыми режимами,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством Российской Федерации о налогах и сборах в бюджет субъекта Российской Федерации; (В редакции Федерального закона от 29.11.2010 № 313-ФЗ)\n\nединые для всех городских округов с внутригородским делением субъекта Российской Федерации нормативы отчислений в бюджеты городских округов с внутригородским делением от отдельных федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  и (или)  региональных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством Российской Федерации о налогах и сборах в бюджет субъекта Российской Федерации; (Дополнение абзацем - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\nединые для всех внутригородских районов городских округов с внутригородским делением субъекта Российской Федерации нормативы отчислений в бюджеты внутригородских районов городских округов с внутригородским делением от отдельных федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  и (или)  региональных налогов,  подлежащих зачислению в соответствии с настоящим Кодексом и законодательством Российской Федерации о налогах и сборах в бюджет субъекта Российской Федерации. (Дополнение абзацем - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n11. В случае,  если законом субъекта Российской Федерации установлено,  что проекты бюджетов муниципальных районов,  муниципальных округов,  городских округов,  городских округов с внутригородским делением,  внутригородских районов составляются и утверждаются сроком на три года (очередной финансовый год и плановый период) ,  не допускается снижение установленных в соответствии с пунктом 1 настоящей статьи единых нормативов отчислений в бюджеты муниципальных районов,  муниципальных округов,  городских округов,  городских округов с внутригородским делением,  внутригородских районов от отдельных федеральных и (или)  региональных налогов и сборов,  налогов,  предусмотренных специальными налоговыми режимами,  в течение трех лет с момента вступления в силу закона субъекта Российской Федерации о сроке составления и утверждения бюджетов муниципальных районов,  муниципальных округов,  городских округов,  городских округов с внутригородским делением,  внутригородских районов и (или)  об установлении единых нормативов отчислений в бюджеты муниципальных районов,  муниципальных округов,  городских округов,  городских округов с внутригородским делением,  внутригородских районов соответственно,  за исключением случаев внесения федеральными законами изменений,  приводящих к перераспределению полномочий и (или)  доходов бюджетов между субъектами Российской Федерации и муниципальными районами,  муниципальными округами,  городскими округами,  городскими округами с внутригородским делением,  городскими поселениями,  сельскими поселениями,  внутригородскими районами,  и (или)  внесения законами субъекта Российской Федерации и принятыми в соответствии с ними уставом муниципального района (городского округа с внутригородским делением)  и уставами сельских поселений (внутригородских районов)  изменений,  приводящих к перераспределению вопросов местного значения и (или)  доходов бюджетов между муниципальным районом и сельским поселением,  городским округом с внутригородским делением и внутригородским районом. (Дополнение пунктом - Федеральный закон от 03.12.2012 № 244-ФЗ)  (В редакции федеральных законов от 29.11.2014 № 383-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\n2. Законом субъекта Российской Федерации о бюджете субъекта Российской Федерации в порядке,  предусмотренном статьями 137 и 138 настоящего Кодекса,  могут быть установлены дополнительные нормативы отчислений в местные бюджеты от налога на доходы физических лиц,  подлежащего зачислению в соответствии с настоящим Кодексом в бюджет субъекта Российской Федерации. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\nЗаконом субъекта Российской Федерации представительные органы муниципальных районов (городских округов с внутригородским делением)  могут быть наделены полномочиями органов государственной власти субъектов Российской Федерации по установлению дополнительных нормативов отчислений от налога на доходы физических лиц,  подлежащего зачислению в бюджет субъекта Российской Федерации,  в бюджеты городских,  сельских поселений (внутригородских районов) ,  входящих в состав соответствующих муниципальных районов (городских округов с внутригородским делением) . (В редакции Федерального закона от 29.11.2014 № 383-ФЗ)\n\n3. Органы государственной власти субъекта Российской Федерации обязаны установить в порядке,  предусмотренном настоящей статьей,  единые и (или)  дополнительные нормативы отчислений в местные бюджеты от налога на доходы физических лиц,  исходя из зачисления в местные бюджеты не менее 15 процентов налоговых доходов консолидированного бюджета субъекта Российской Федерации от указанного налога. (В редакции федеральных законов от 30.11.2011 № 361-ФЗ; от 23.07.2013 № 252-ФЗ)\n\n31. Органы государственной власти субъекта Российской Федерации обязаны установить дифференцированные нормативы отчислений в местные бюджеты от акцизов на автомобильный и прямогонный бензин,  дизельное топливо,  моторные масла для дизельных и (или)  карбюраторных (инжекторных)  двигателей,  производимые на территории Российской Федерации,  исходя из зачисления в местные бюджеты не менее 10 процентов налоговых доходов консолидированного бюджета субъекта Российской Федерации от указанного налога.\n\nПри определении в соответствии с абзацем первым настоящего пункта дифференцированных нормативов отчислений в местные бюджеты учитываются поступления в бюджеты субъектов Российской Федерации от указанных в абзаце первом настоящего пункта акцизов исходя из норматива 53, 2 процента. (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\nРазмеры указанных дифференцированных нормативов отчислений в местные бюджеты устанавливаются исходя из протяженности автомобильных дорог общего пользования местного значения соответствующих муниципальных образований,  органы местного самоуправления которых решают вопросы местного значения в сфере дорожной деятельности. (В редакции федеральных законов от 22.10.2014 № 311-ФЗ; от 29.11.2014 № 383-ФЗ)\n\nПри расчете указанных нормативов помимо протяженности автомобильных дорог общего пользования могут учитываться виды покрытий автомобильных дорог в порядке,  определяемом законом субъекта\n\nастков и земельных участков,  находящихся в собственности субъектов Российской Федерации,  - по нормативу 100 процентов;\n\nплаты по соглашениям об установлении сервитута,  заключенным исполнительными органами субъектов Российской Федерации,  государственными или муниципальными предприятиями либо государственными или муниципальными учреждениями в отношении земельных участков,  находящихся в собственности субъектов Российской Федерации,  - по нормативу 100 процентов; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nплаты за увеличение площади земельных участков,  находящихся в частной собственности,  в результате перераспределения таких земельных участков и земельных участков,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  - по нормативу не более 50 процентов;\n\nплаты по соглашениям об установлении сервитута,  заключенным исполнительными органами субъектов Российской Федерации,  государственными или муниципальными предприятиями либо государственными или муниципальными учреждениями в отношении земельных участков,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  - по нормативу не более 50 процентов; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nплаты за публичный сервитут,  предусмотренной решением уполномоченного органа об установлении публичного сервитута в отношении земельных участков,  которые находятся в собственности субъектов Российской Федерации и не предоставлены гражданам или юридическим лицам (за исключением органов государственной власти (государственных органов) ,  органов местного самоуправления (муниципальных органов) ,  органов управления государственными внебюджетными фондами и казенных учреждений) ,  - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\nплаты за публичный сервитут,  предусмотренной решением уполномоченного органа об установлении публичного сервитута в отношении земельных участков,  которые находятся в федеральной собственности,  осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации и которые не предоставлены гражданам или юридическим лицам (за исключением органов государственной власти (государственных органов) ,  органов местного самоуправления (муниципальных органов) ,  органов управления государственными внебюджетными фондами и казенных учреждений) ,  - по нормативу не более 50 процентов; (Дополнение абзацем - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\nплаты за предоставление публично-правовой компанией в сфере государственного кадастрового учета и государственной регистрации прав сведений,  документов,  содержащихся в государственных реестрах,  в случае,  когда предоставление указанных документов осуществляется через многофункциональный центр предоставления государственных и муниципальных услуг,  а также в случае подачи заявления о предоставлении сведений,  документов,  содержащихся в государственных реестрах,  в электронной форме и выдачи указанных документов через многофункциональный центр предоставления государственных и муниципальных услуг - по нормативу 15 процентов. (Дополнение абзацем - Федеральный закон от 21.11.2022 № 448-ФЗ)\n\n(Часть в редакции Федерального закона от 07.03.2018 № 45-ФЗ)\n\nВ бюджеты субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя подлежат зачислению: (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nплата за негативное воздействие на окружающую среду - по нормативу 100 процентов; (В редакции федеральных законов от 03.12.2012 № 244-ФЗ,  от 15.04.2019 № 62-ФЗ)\n\nдоходы от передачи в аренду земельных участков,  государственная собственность на которые не разграничена и которые расположены в границах городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  а также средства от продажи права на заключение договоров аренды указанных земельных участков - по нормативу 100 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное; (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nдоходы от продажи земельных участков,  государственная собственность на которые не разграничена и которые расположены в границах городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  - по нормативу 100 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное; (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\nдоходы от продажи земельных участков,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  передачи в аренду таких земельных участков,  продажи прав на заключение договоров аренды таких земельных участков - по нормативу 100 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное; (Дополнение абзацем - Федеральный закон от 24.07.2008 № 161-ФЗ)\n\nдоходы от продажи объектов недвижимого имущества одновременно с занятыми такими объектами недвижимого имущества земельными участками,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  - по нормативу 100 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное; (Дополнение абзацем - Федеральный закон от 24.07.2008 № 161-ФЗ)\n\nплата за снятие запрета на реконструкцию,  строительство зданий,  строений,  сооружений на земельном участке - по нормативу 100 процентов; (Дополнение абзацем - Федеральный закон от 24.07.2007 № 212-ФЗ)\n\nплата за увеличение площади земельных участков,  находящихся в частной собственности,  в результате перераспределения таких земельных участков и земель и (или)  земельных участков,  государственная собственность на которые не разграничена и которые расположены в границах городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  либо за увеличение площади земельных участков,  находящихся в частной собственности,  в результате перераспределения таких земельных участков и земельных участков,  находящихся в собственности этих субъектов Российской Федерации,  - по нормативу 100 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное; (Дополнение абзацем - Федеральный закон от 26.12.2014 № 450-ФЗ)\n\nплата по соглашениям об установлении сервитута,  заключенным государственными (муниципальными)  органами,  государственными или муниципальными предприятиями либо государственными или муниципальными учреждениями в отношении земельных участков,  находящихся в собственности субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  или земельных участков,  государственная собственность на которые не разграничена и которые расположены в границах городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  - по нормативу 100 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное; (Дополнение абзацем - Федеральный закон от 26.12.2014 № 450-ФЗ)  (В редакции Федерального закона от 29.12.2015 № 406-ФЗ)\n\nплата за увеличение площади земельных участков,  находящихся в частной собственности,  в результате перераспределения таких земельных участков и земельных участков,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  - по нормативу 100 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное; (Дополнение абзацем - Федеральный закон от 26.12.2014 № 450-ФЗ)\n\nплата по соглашениям об установлении сервитута,  заключенным исполнительными органами субъектов Российской Федерации,  государственными или муниципальными предприятиями либо государственными или муниципальными учреждениями в отношении земельных участков,  которые находятся в федеральной собственности и осуществление полномочий Российской Федерации по управлению и распоряжению которыми передано органам государственной власти субъектов Российской Федерации,  - по нормативу 100 процентов,  если законодательством соответствующего субъекта Российской Федерации не установлено иное; (Дополнение абзацем - Федеральный закон от 26.12.2014 № 450-ФЗ)  (В редакции  Феде